// ── Registry ─────────────────────────────────────────────────────────────────
/**
 * Every course that has a resource library, keyed by the short code in
 * lib/catalog.ts. A course listed here must also declare a `library` track in
 * its catalogue entry, or the shelf exists but nothing links to it.
 */
export const SUBJECT_ASSETS: Record<string, SubjectAsset[]> = {
  ITF: ITF_ASSETS,
  ICS: ICS_ASSETS,
  MFIT: MFIT_ASSETS,
  PSCP: PSCP_ASSETS,
  CHARM: CHARM_ASSETS,
  FE: FE_ASSETS,
  OOP: OOP_ASSETS,
  DSA: DSA_ASSETS,
  PSTAT: PSTAT_ASSETS,
  BFIT: BFIT_ASSETS,
  FE2: FE2_ASSETS,
  DL: DL_ASSETS,
  COMPRO: COMPRO_ASSETS,
  CHEM: CHEM_ASSETS,
};

/**
 * Every asset generated from the file tree by scripts/build-library-manifest.mjs.
 *
 * These are the floor beneath SUBJECT_ASSETS: a file dropped into
 * public/assets/<ns>/<subject>/<category>/ gets a card from its filename alone,
 * so nothing on disk is invisible in the gallery. Titles are derived, and
 * `scope` is deliberately absent — see that script's header for why.
 */
const GENERATED_ASSETS = LIBRARY_MANIFEST as Record<string, SubjectAsset[]>;

/**
 * Curated entries followed by whatever the manifest found that they don't
 * already cover, matched on url. A hand-written entry carries a bilingual
 * title, a description and an exam scope that a filename cannot, so it always
 * wins over the generated card for the same file.
 */
export function mergedAssets(code: string): SubjectAsset[] {
  const key = code.toUpperCase();
  const curated = SUBJECT_ASSETS[key] ?? [];
  const claimed = new Set(curated.map((a) => a.url.split("#")[0]));
  const generated = (GENERATED_ASSETS[key] ?? []).filter(
    (a) => !claimed.has(a.url.split("#")[0]),
  );
  return [...curated, ...generated];
}

/** Course codes that have at least one asset, curated or generated. */
export function coursesWithAssets(): Set<string> {
  return new Set([...Object.keys(SUBJECT_ASSETS), ...Object.keys(GENERATED_ASSETS)]);
}

/**
 * A course's freely-viewable library assets, with page counts and file sizes
 * filled in and `url` rewritten to Supabase Storage.
 *
 * Past exams are NOT here. They are insider-only (see isRestrictedAsset), they
 * live in a private bucket, and they are reachable only through
 * restrictedAssetsForCourse() behind a role check. Excluding them at this level
 * — rather than hiding them in the UI — is what keeps their titles and
 * filenames out of the statically prerendered HTML for these pages.
 *
 * Order matters: withAssetStats() keys off the original "/assets/…" path, so
 * the rewrite has to come last. Everything downstream — the gallery, the
 * preview modal, the download link — just uses `url` and never learns where
 * the bytes live.
 */
export function assetsForCourse(code: string): SubjectAsset[] | undefined {
  const assets = mergedAssets(code).filter((asset) => !isRestrictedAsset(asset));
  if (!assets.length) return undefined;
  return withAssetStats(assets).map((asset) => ({ ...asset, url: assetUrl(asset.url) }));
}

/**
 * A course's past exams, still carrying their original "/assets/…" path.
 *
 * Deliberately returns no usable URL: the caller has to mint a signed one after
 * authorizing the reader (see lib/library-exams.ts). Exported for that module
 * and for the counts on the course hub, not for rendering.
 */
export function restrictedAssetsForCourse(code: string): SubjectAsset[] {
  return withAssetStats(mergedAssets(code).filter(isRestrictedAsset));
}
